INSERT INTO public.flashcards (deck_category, front_content, back_content) VALUES
('Fundamentos de Enfermagem', 'O que é a manobra de Heimlich e para que serve?', 'É uma técnica de primeiros socorros utilizada em casos de engasgo (obstrução de vias aéreas por corpo estranho). Consiste em compressões abdominais vigorosas (em formato de J) acima do umbigo para expulsar o objeto.'),
('Fundamentos de Enfermagem', 'Qual é a diferença entre Asepsia e Antissepsia?', 'Asepsia: conjunto de medidas para IMPEDIR a entrada de microrganismos em um ambiente/paciente (ex: lavar as mãos, campo estéril). Antissepsia: uso de substâncias químicas (antissépticos) em tecidos vivos (pele/mucosa) para DESTRUIR ou inibir microrganismos.'),
('Fundamentos de Enfermagem', 'O que indica um Teste de Allen positivo e antes de qual procedimento ele é obrigatório?', 'Indica boa perfusão da artéria ulnar e arco palmar (a mão volta a corar rapidamente). É obrigatório antes de realizar a punção de gasometria arterial na artéria radial para evitar isquemia da mão.'),
('Fundamentos de Enfermagem', 'O que é o volume residual e o que é o resíduo gástrico?', 'Resíduo gástrico é o volume de líquido aspirado do estômago antes da administração da dieta enteral. Se for superior a determinado volume (geralmente > 200-500ml dependendo do protocolo), indica retardo no esvaziamento gástrico, devendo a dieta ser pausada.'),
('Fundamentos de Enfermagem', 'Quais são as fases do Processo de Enfermagem (SAE) segundo a Resolução COFEN 358/2009?', '1. Coleta de dados de enfermagem (Histórico); 2. Diagnóstico de enfermagem; 3. Planejamento de enfermagem; 4. Implementação; 5. Avaliação de enfermagem.'),
('Fundamentos de Enfermagem', 'O que é claudicação intermitente?', 'Dor muscular intensa, geralmente na panturrilha (barriga da perna), que ocorre durante o exercício/caminhada e melhora com o repouso. É um sinal clássico de doença arterial obstrutiva periférica.'),
('Fundamentos de Enfermagem', 'Como deve ser o posicionamento do paciente para a administração de medicação via retal (supositório)?', 'Posição de Sims (decúbito lateral esquerdo com a perna direita fletida). Essa posição respeita a anatomia do cólon descendente, facilitando a introdução e retenção do medicamento.'),
('Fundamentos de Enfermagem', 'Qual é a principal complicação mecânica associada à manutenção prolongada de Sonda Nasogástrica/Nasoentérica?', 'Lesão e necrose da asa do nariz (devido à pressão mal distribuída na fixação).'),
('Fundamentos de Enfermagem', 'O que é um curativo primário e um curativo secundário?', 'Curativo Primário: é o que fica em contato direto com a ferida (ex: gaze, hidrocolóide, pomada). Curativo Secundário: é o que cobre o primário, com função de fixação e absorção de exsudato em excesso.'),
('Fundamentos de Enfermagem', 'Defina Anúria, Oligúria, Poliúria e Disúria.', 'Anúria: ausência ou volume < 100ml em 24h. Oligúria: redução, < 400ml em 24h. Poliúria: aumento, > 2.500ml a 3.000ml em 24h. Disúria: dor ou ardência ao urinar.'),
('Fundamentos de Enfermagem', 'Na técnica de punção venosa periférica com cateter agulhado (Scalp), o bisel da agulha deve estar voltado para qual direção?', 'Bisel sempre voltado para CIMA, para facilitar a perfuração da pele e da veia com menor trauma tecidual.'),
('Fundamentos de Enfermagem', 'Qual o principal cuidado de enfermagem imediato após a administração de medicação via sonda nasoentérica?', 'Lavar a sonda com 20 a 30ml de água filtrada (ou água destilada, conforme protocolo da instituição) para garantir que toda a medicação chegou ao estômago/intestino e evitar obstrução do lúmen da sonda.'),
('Fundamentos de Enfermagem', 'O que são as precauções de contato e quais EPIs são exigidos?', 'Medidas para evitar transmissão por contato direto (pele com pele) ou indireto (superfícies/artigos). EPIs obrigatórios: Luvas e Avental (Avental se houver risco de contato da roupa com secreções/paciente). Ex: KPC, VRE, MRSA, Escabiose.'),
('Fundamentos de Enfermagem', 'Qual é o tipo de precaução recomendada para Tuberculose pulmonar bacilífera e Sarampo?', 'Precaução por Aerossóis (partículas menores que 5 micra que ficam suspensas no ar). O profissional deve usar máscara N95/PFF2 ao entrar no quarto.'),
('Fundamentos de Enfermagem', 'Em um ECG normal, o que representa a Onda P, Complexo QRS e Onda T?', 'Onda P: Despolarização (contração) dos átrios. Complexo QRS: Despolarização dos ventrículos. Onda T: Repolarização (relaxamento) dos ventrículos.'),
('Fundamentos de Enfermagem', 'O que é flebite e quais os seus sinais clássicos?', 'Flebite é a inflamação de uma veia, muitas vezes relacionada a acessos venosos periféricos. Sinais: Dor, eritema (vermelhidão) no trajeto da veia, edema e cordão venoso palpável/endurecido.'),
('Fundamentos de Enfermagem', 'Qual a sequência correta da higienização simples das mãos (fricção das partes)?', '1. Palmas; 2. Dorso de ambas as mãos; 3. Espaços interdigitais; 4. Dorso dos dedos (articulações); 5. Polegares; 6. Polpas digitais e unhas (friccionadas na palma da mão oposta); 7. Punhos.'),
('Fundamentos de Enfermagem', 'O que significa o termo "Iatrogenia" na prática de enfermagem?', 'Dano, complicação ou doença causada de forma não intencional como resultado de intervenção, tratamento ou erro de profissionais de saúde (ex: erro de medicação, infecção cruzada).'),
('Fundamentos de Enfermagem', 'O que é a Escala de Braden e o que ela avalia?', 'É uma escala preditiva utilizada para avaliar o risco do paciente desenvolver Lesão por Pressão (LPP). Quanto MENOR a pontuação, MAIOR o risco. Avalia: Percepção sensorial, Umidade, Atividade, Mobilidade, Nutrição e Fricção/Cisalhamento.'),
('Fundamentos de Enfermagem', 'Ao aspirar medicamentos em ampolas de vidro, qual cuidado com o material puncionante o Cofen recomenda (embora nem sempre viável na prática da emergência)?', 'Recomenda-se o uso de agulha com filtro para aspiração, a fim de evitar a injeção acidental de microfragmentos de vidro que podem cair dentro da ampola no momento da quebra.');